3. 麦克风输入
abstract class MicPcmInput {
  Stream<List<int>> get stream;

  Future<void> start({
    int sampleRate = 16000,
    int channels = 1,
  });

  Future<void> stop();
}

实现用 record：

class RecordMicPcmInput implements MicPcmInput {
  final AudioRecorder _recorder = AudioRecorder();

  Stream<List<int>>? _stream;

  @override
  Stream<List<int>> get stream {
    final s = _stream;
    if (s == null) {
      throw StateError('Mic input is not started.');
    }
    return s;
  }

  @override
  Future<void> start({
    int sampleRate = 16000,
    int channels = 1,
  }) async {
    _stream = await _recorder.startStream(
      RecordConfig(
        encoder: AudioEncoder.pcm16bits,
        sampleRate: sampleRate,
        numChannels: channels,
        echoCancel: true,
        noiseSuppress: true,
        autoGain: true,
      ),
    );
  }

  @override
  Future<void> stop() async {
    await _recorder.stop();
    _stream = null;
  }
}

如果你的 record 版本支持 Android audio source，补上 voiceCommunication。

4. TTS PCM 输出

接口：

abstract class TtsPcmOutput {
  Stream<bool> get playbackActive;

  Future<void> start({
    int sampleRate = 16000,
    int channels = 1,
  });

  Future<void> push(List<int> pcm);

